-- Public chat for the Quickly pitch. Does not send email.
update public.configurators c
set chat_enabled = true
from public.organizations o
where c.organization_id = o.id
  and o.slug = 'quickly'
  and c.slug = 'rayonnage'
  and c.chat_enabled = false;

-- Draft relance sequences for org quickly. Does not send email.
-- Pauses only the auto-seeded parcours names. Named Quickly drafts inserted below stay draft
-- until someone sets them active in the app (this file does not run again).

update public.workflows w
set status = 'draft', updated_at = now()
from public.organizations o
where w.organization_id = o.id
  and o.slug = 'quickly'
  and w.status = 'active'
  and w.name in ('Parcours demande', 'Parcours abandon');

insert into public.workflows (organization_id, name, status, trigger_type, trigger_config, definition)
select o.id, v.name, 'draft', v.trigger_type, v.trigger_config, v.definition
from public.organizations o
cross join (values
  ('Relance abandon — Quickly', 'session.abandoned', '{"silentDraft":true}'::jsonb, '{"nodes":[{"id":"trigger","type":"trigger","position":{"x":360,"y":0},"data":{"label":"Session abandonnée"}},{"id":"wait-1h","type":"wait","position":{"x":80,"y":160},"data":{"label":"Inactif 1 h","waitHours":1,"waitFrom":"last_activity"}},{"id":"mail-resume","type":"send_email","position":{"x":80,"y":320},"data":{"label":"Reprise de session","templateKind":"session_resume","recipient":"prospect"}},{"id":"wait-24h","type":"wait","position":{"x":560,"y":160},"data":{"label":"Inactif 24 h","waitHours":24,"waitFrom":"last_activity"}},{"id":"mail-late","type":"send_email","position":{"x":560,"y":320},"data":{"label":"Seconde relance","templateKind":"session_resume_late","recipient":"prospect"}}],"edges":[{"id":"e-trigger-out-wait-1h","source":"trigger","target":"wait-1h","sourceHandle":null},{"id":"e-wait-1h-out-mail-resume","source":"wait-1h","target":"mail-resume","sourceHandle":null},{"id":"e-trigger-out-wait-24h","source":"trigger","target":"wait-24h","sourceHandle":null},{"id":"e-wait-24h-out-mail-late","source":"wait-24h","target":"mail-late","sourceHandle":null}]}'::jsonb),
  ('Relance après demande — Quickly', 'quote.submitted', '{"silentDraft":true}'::jsonb, '{"nodes":[{"id":"trigger","type":"trigger","position":{"x":640,"y":0},"data":{"label":"Demande soumise"}},{"id":"mail-confirm","type":"send_email","position":{"x":40,"y":160},"data":{"label":"Confirmation prospect","templateKind":"prospect_confirm","recipient":"prospect","attachPdf":true}},{"id":"mail-sales","type":"send_email","position":{"x":360,"y":160},"data":{"label":"Brief commercial","templateKind":"sales_brief","recipient":"sales_email"}},{"id":"wait-4h","type":"wait","position":{"x":680,"y":160},"data":{"label":"Attendre 4 h","waitHours":4,"waitFrom":"now"}},{"id":"branch-new","type":"branch","position":{"x":680,"y":320},"data":{"label":"Encore Nouveau ?","conditions":[{"id":"yes","field":"status","op":"eq","value":"new"}]}},{"id":"mail-unprocessed","type":"send_email","position":{"x":560,"y":480},"data":{"label":"Rappel interne","templateKind":"sales_unprocessed","recipient":"assignee"}},{"id":"exit-new","type":"exit","position":{"x":840,"y":480},"data":{"label":"Déjà pris en charge"}},{"id":"wait-24h","type":"wait","position":{"x":1040,"y":160},"data":{"label":"Attendre 24 h","waitHours":24,"waitFrom":"now"}},{"id":"branch-24","type":"branch","position":{"x":1040,"y":320},"data":{"label":"Dossier ouvert ?","conditions":[{"id":"open","field":"is_closed","op":"eq","value":false}]}},{"id":"mail-reassure","type":"send_email","position":{"x":920,"y":480},"data":{"label":"Email rassurant","templateKind":"prospect_reassure","recipient":"prospect"}},{"id":"exit-24","type":"exit","position":{"x":1200,"y":480},"data":{"label":"Dossier clos"}},{"id":"wait-photo","type":"wait","position":{"x":1400,"y":160},"data":{"label":"Attendre 24 h","waitHours":24,"waitFrom":"now"}},{"id":"branch-photo","type":"branch","position":{"x":1400,"y":320},"data":{"label":"Dossier ouvert ?","conditions":[{"id":"open","field":"is_closed","op":"eq","value":false}]}},{"id":"mail-photo","type":"send_email","position":{"x":1280,"y":480},"data":{"label":"Demande de photo","templateKind":"prospect_photo","recipient":"prospect"}},{"id":"exit-photo","type":"exit","position":{"x":1560,"y":480},"data":{"label":"Dossier clos"}},{"id":"wait-72h","type":"wait","position":{"x":1760,"y":160},"data":{"label":"Attendre 3 j","waitHours":72,"waitFrom":"now"}},{"id":"branch-72","type":"branch","position":{"x":1760,"y":320},"data":{"label":"Dossier ouvert ?","conditions":[{"id":"open","field":"is_closed","op":"eq","value":false}]}},{"id":"mail-followup","type":"send_email","position":{"x":1640,"y":480},"data":{"label":"Relance douce","templateKind":"prospect_followup","recipient":"prospect"}},{"id":"exit-72","type":"exit","position":{"x":1920,"y":480},"data":{"label":"Dossier clos"}}],"edges":[{"id":"e-trigger-out-mail-confirm","source":"trigger","target":"mail-confirm","sourceHandle":null},{"id":"e-trigger-out-mail-sales","source":"trigger","target":"mail-sales","sourceHandle":null},{"id":"e-trigger-out-wait-4h","source":"trigger","target":"wait-4h","sourceHandle":null},{"id":"e-trigger-out-wait-24h","source":"trigger","target":"wait-24h","sourceHandle":null},{"id":"e-trigger-out-wait-photo","source":"trigger","target":"wait-photo","sourceHandle":null},{"id":"e-trigger-out-wait-72h","source":"trigger","target":"wait-72h","sourceHandle":null},{"id":"e-wait-4h-out-branch-new","source":"wait-4h","target":"branch-new","sourceHandle":null},{"id":"e-branch-new-yes-mail-unprocessed","source":"branch-new","target":"mail-unprocessed","sourceHandle":"yes"},{"id":"e-branch-new-else-exit-new","source":"branch-new","target":"exit-new","sourceHandle":"else"},{"id":"e-wait-24h-out-branch-24","source":"wait-24h","target":"branch-24","sourceHandle":null},{"id":"e-branch-24-open-mail-reassure","source":"branch-24","target":"mail-reassure","sourceHandle":"open"},{"id":"e-branch-24-else-exit-24","source":"branch-24","target":"exit-24","sourceHandle":"else"},{"id":"e-wait-photo-out-branch-photo","source":"wait-photo","target":"branch-photo","sourceHandle":null},{"id":"e-branch-photo-open-mail-photo","source":"branch-photo","target":"mail-photo","sourceHandle":"open"},{"id":"e-branch-photo-else-exit-photo","source":"branch-photo","target":"exit-photo","sourceHandle":"else"},{"id":"e-wait-72h-out-branch-72","source":"wait-72h","target":"branch-72","sourceHandle":null},{"id":"e-branch-72-open-mail-followup","source":"branch-72","target":"mail-followup","sourceHandle":"open"},{"id":"e-branch-72-else-exit-72","source":"branch-72","target":"exit-72","sourceHandle":"else"}]}'::jsonb)
) as v(name, trigger_type, trigger_config, definition)
where o.slug = 'quickly'
  and not exists (
    select 1 from public.workflows w
    where w.organization_id = o.id and w.name = v.name
  );
